19: int
20: ImagingPcxDecode(Imaging im, ImagingCodecState state, UINT8* buf, Py_ssize_t bytes)
21: {
22:     UINT8 n;
23:     UINT8* ptr;
24: 
25:     if (strcmp(im->mode, "1") == 0 && state->xsize > state->bytes * 8) {
26:         state->errcode = IMAGING_CODEC_OVERRUN;
27:         return -1;
28:     } else if (strcmp(im->mode, "P") == 0 && state->xsize > state->bytes) {
29:         state->errcode = IMAGING_CODEC_OVERRUN;
30:         return -1;
31:     }
32: 
33:     ptr = buf;
34: 
35:     for (;;) {
36: 
37: 	if (bytes < 1)
38: 	    return ptr - buf;
39: 
40: 	if ((*ptr & 0xC0) == 0xC0) {
41: 
42: 	    /* Run */
43: 	    if (bytes < 2)
44: 		return ptr - buf;
45: 
46: 	    n = ptr[0] & 0x3F;
47: 
48: 	    while (n > 0) {
49: 		if (state->x >= state->bytes) {
50: 		    state->errcode = IMAGING_CODEC_OVERRUN;
51: 		    break;
52: 		}
53: 		state->buffer[state->x++] = ptr[1];
54: 		n--;
55: 	    }
56: 
57: 	    ptr += 2; bytes -= 2;
58: 
59: 	} else {
60: 
61: 	    /* Literal */
62: 	    state->buffer[state->x++] = ptr[0];
63: 	    ptr++; bytes--;
64: 
65: 	}
66: 
67: 	if (state->x >= state->bytes) {
68:         if (state->bytes % state->xsize && state->bytes > state->xsize) {
69:             int bands = state->bytes / state->xsize;
70:             int stride = state->bytes / bands;
71:             int i;
72:             for (i=1; i< bands; i++) {  // note -- skipping first band
73:                 memmove(&state->buffer[i*state->xsize],
74:                         &state->buffer[i*stride],
75:                         state->xsize);
76:             }
77:         }
78: 	    /* Got a full line, unpack it */
79: 	    state->shuffle((UINT8*) im->image[state->y + state->yoff] +
80: 			   state->xoff * im->pixelsize, state->buffer,
81: 			   state->xsize);
82: 
83: 	    state->x = 0;
84: 
85: 	    if (++state->y >= state->ysize) {
86: 		/* End of file (errcode = 0) */
87: 		return -1;
88: 	    }
89: 	}
90: 
91:     }
